const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
export const GRAPH_NODES=[
 {id:'project',x:280,y:25,w:340,h:62,lines:['Anna: Editionsprojekt'],info:'Anna möchte einen historischen Text wissenschaftlich erschließen. Die Übersicht zeigt mögliche Wege. Eine hervorgehobene Auswahl bedeutet eine Planung, keine bereits ausgeführte Einrichtung.'},
 {id:'format',x:320,y:135,w:260,h:64,lines:['Arbeitsformat?'],question:true,info:'TEI und Markdown sind zwei Arbeitswege. TEI bietet etablierte editorische Semantik; Markdown benötigt eigene Konventionen und bleibt die weniger bevorzugte Alternative. Beide können mit Git versioniert werden.'},
 {id:'tei',x:60,y:270,w:300,h:80,lines:['oXygen Author','TEI + vorbereitetes Schema'],field:'format',value:'tei',info:'Anna wählt TEI und eine vorbereitete oXygen-Author-Umgebung. Schema, Vorlagen und Git-Anbindung erleichtern die Arbeit. Die Auswahl setzt das Arbeitsformat auf TEI; ein tatsächlicher Werkzeugzugang ist noch zu klären.'},
 {id:'markdown',x:540,y:270,w:300,h:80,lines:['Texteditor mit Vorschau','Markdown + Konventionen'],field:'format',value:'markdown',info:'Anna kann mit Markdown arbeiten und regelmäßig eine Vorschau prüfen. Eigene Regeln für editorische Aussagen, IDs und Verweise sind nötig. Die Auswahl setzt den alternativen Arbeitsweg; sie behauptet keine TEI-vergleichbare Semantik.'},
 {id:'data',x:280,y:410,w:340,h:68,lines:['Git-gestützte Quelldaten'],info:'Die beiden Formatwege führen wieder zusammen: Dateien und gespeicherte Änderungen werden mit Git versioniert. Unterschiedliche Semantik, Prüfungen und Ausgabewege bleiben bestehen.'},
 {id:'workhost',x:320,y:535,w:260,h:64,lines:['Arbeits-Host?'],question:true,info:'Hier geht es um den Ort des privaten Arbeitsrepos. Hosting und Beratung sind unterschiedliche Leistungen. Die Wahl legt den späteren Publikationsort nicht zwingend fest.'},
 {id:'uni',x:60,y:670,w:300,h:80,lines:['Institutionelles GitLab','Beratung gesondert klären'],field:'host',value:'uni-support',info:'Anna kann ein institutionelles GitLab nutzen. Der Knoten wählt das Modellangebot mit Beratung; in der Auswahl links kann sie auch reines Hosting einstellen. Zugang, Beratung und langfristige Kontinuität sind konkret zu klären.'},
 {id:'other',x:540,y:670,w:300,h:80,lines:['GitHub / anderer Dienst','Zugang und Unterstützung klären'],field:'host',value:'other',info:'Ein individuell gewählter geeigneter Dienst kann das private Arbeitsrepo aufnehmen. GitHub ist ein Beispiel. Anna klärt Konto, Verfügung, Unterstützung und Sicherungsweg. Ein anderer Dienst bestimmt noch keinen öffentlichen Publikationsort.'},
 {id:'pubhost',x:320,y:815,w:260,h:64,lines:['Publikations-Host?'],question:true,info:'Gleicher oder anderer Hostingdienst? Das ist eine andere Frage als dieselbes oder separates Repo. Für Anna bleibt ein eigenes Publikationsrepo mit bereinigten Dateien die bevorzugte Architektur – auf beiden Host-Wegen.'},
 {id:'same',x:60,y:950,w:300,h:84,lines:['Eigenes Publikationsrepo','auf demselben Host'],field:'publicationHost',value:'same',info:'Anna plant ein separates öffentliches Publikationsrepo beim bisherigen Hostingdienst. Sie übernimmt nur geprüfte Dateien ohne private Arbeitsgeschichte. Gleicher Host bedeutet ausdrücklich nicht, das private Arbeitsrepo öffentlich zu machen.'},
 {id:'different',x:540,y:950,w:300,h:84,lines:['Eigenes Publikationsrepo','auf einem anderen Host'],field:'publicationHost',value:'other',info:'Anna kann privat auf dem Uni-GitLab arbeiten und einen bereinigten Stand etwa auf einem anderen Dienst publizieren. Auch hier ist es ein separates Publikationsrepo. Export, Zugriff und Ausgabeweg werden passend eingerichtet.'},
 {id:'release',x:280,y:1110,w:340,h:70,lines:['Geprüfter Release','nach bewusster Freigabe'],info:'Die Wege laufen bei einer fachlich verantworteten Freigabe zusammen. Vorher werden Inhalt, Rechte, Metadaten, Attribution und erreichbare Publikationsgeschichte geprüft. Eine noch interne Arbeit oder ein Prüfausschnitt ist noch kein öffentlicher Release.'},
 {id:'archive',x:20,y:1280,w:260,h:90,lines:['Editionsdaten','+ vereinbarte Archivübergabe'],info:'Freigegebene TEI- oder andere dokumentierte Editionsdaten werden nachnutzbar bereitgestellt. Archivträger, Metadaten und persistente Kennung sind zusätzlich zu vereinbaren. Ein Git-Host allein garantiert die Archivierung nicht.'},
 {id:'web',x:320,y:1280,w:260,h:90,lines:['Statische Website','z. B. über GitHub Pages'],info:'Eine kleine Website macht Text und Kommentar ohne TEI-Kenntnisse lesbar. Die freigegebenen Daten benötigen einen passenden Ausgabeweg zu HTML. GitHub Pages ist ein möglicher statischer Hostingdienst; es erzeugt nicht automatisch eine Edition aus rohen TEI-Dateien.'},
 {id:'print',x:620,y:1280,w:260,h:90,lines:['Optionale Druckfassung','mit oder ohne Verlag'],info:'Aus einem geprüften Stand kann mit geeigneter Satzvorlage eine Druckfassung entstehen. Ein Verlag ist eine Chance mit Kosten-, Leistungs- und Rechtefragen. Spätere digitale Revisionen verändern verteilte Druckexemplare nicht.'}
];
export function graphSVG(state=null,interactive=false){
 const has=!!state;const f=state?.format,h=state?.host,p=state?.publicationHost;const publishing=state?.release==='public';
 const chosen=id=>has&&(['project','format','data','workhost','pubhost'].includes(id)||(id==='tei'&&f==='tei')||(id==='markdown'&&f==='markdown')||(id==='uni'&&h!=='other')||(id==='other'&&h==='other')||(id==='same'&&p==='same')||(id==='different'&&p==='other')||(id==='release'&&publishing));
 const line=(d,on=false,dashed=false)=>`<path d="${d}" fill="none" stroke="${on?'#173c39':'#9baeb4'}" stroke-width="${on?3:1.6}" ${dashed?'stroke-dasharray="6 5"':''} marker-end="url(#${on?'arrow-active':'arrow'})"/>`;
 const pill=(x,y,label)=>`<g aria-hidden="true"><rect x="${x-78}" y="${y-16}" width="156" height="32" rx="16" fill="#f7fbff" stroke="#c5d8e2"/><text x="${x}" y="${y+6}" text-anchor="middle" font-size="17" fill="#244d65">${label}</text></g>`;
 const paths=[line('M450 87V135',has),line('M450 199V230H210V270',f==='tei'),line('M450 199V230H690V270',f==='markdown'),line('M210 350V385H450V410',f==='tei'),line('M690 350V385H450V410',f==='markdown'),line('M450 478V535',has),line('M450 599V630H210V670',has&&h!=='other'),line('M450 599V630H690V670',h==='other'),line('M210 750V785H450V815',has&&h!=='other'),line('M690 750V785H450V815',h==='other'),line('M450 879V910H210V950',p==='same'),line('M450 879V910H690V950',p==='other'),line('M210 1034V1070H450V1110',p==='same'),line('M690 1034V1070H450V1110',p==='other'),line('M450 1180V1225H150V1280',false,true),line('M450 1180V1280',false,true),line('M450 1180V1225H750V1280',false,true)].join('');
 const nodes=GRAPH_NODES.map(n=>{const active=chosen(n.id);const fill=active?'#173c39':n.question?'#f5faff':'#e6f2fc';const attrs=interactive?`data-graph-node="${n.id}" role="button" tabindex="0" aria-label="${esc(n.lines.join(': '))}${n.field?' auswählen und erklären':' erklären'}"`:`role="img" aria-label="${esc(n.lines.join(': '))}"`;
 return `<g ${attrs} class="flow-node${active?' is-chosen':''}" id="flow-${n.id}"><title>${esc(n.info)}</title><rect x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" rx="18" fill="${fill}" stroke="${active?'#173c39':'#bdced9'}" stroke-width="${active?2.5:1.2}" ${n.question?'stroke-dasharray="4 4"':''}/>${n.lines.map((t,i)=>`<text x="${n.x+n.w/2}" y="${n.y+n.h/2+(n.lines.length===1?7:-4)+i*25}" text-anchor="middle" font-size="${i?16:19}" font-weight="${i?400:600}" fill="${active?'#ffffff':'#164b70'}">${esc(t)}</text>`).join('')}${active?`<text x="${n.x+16}" y="${n.y+22}" fill="#ffffff" font-size="15" aria-hidden="true">✓</text>`:''}</g>`;}).join('');
 const note=has?`Arbeitsformat: ${f==='tei'?'TEI':'Markdown'} · Arbeitsort: ${h==='other'?'anderer Dienst':'Uni-GitLab'} · Publikations-Host: ${p==='same'?'gleicher Host':p==='other'?'anderer Host':'noch offen'}`:'Übersicht möglicher Wege · keine Auswahl vorgegeben';
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 1500" width="900" height="1500" class="anna-flow" role="${interactive?'group':'img'}" aria-labelledby="flow-title flow-desc"><title id="flow-title">Anna: Wege vom Editionsprojekt zur Publikation</title><desc id="flow-desc">Arbeitsformat TEI oder Markdown; Zusammenführung bei Git-Quelldaten. Institutionelles oder anderes Hosting; eigenständige Wahl des Publikations-Hosts. Ein eigenes bereinigtes Publikationsrepo auf gleichem oder anderem Host führt zur geprüften Freigabe. Mögliche Ausgaben sind Daten mit vereinbarter Archivierung, Website und Druckfassung.</desc><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M1 1L9 5L1 9" fill="none" stroke="#9baeb4" stroke-width="1.5"/></marker><marker id="arrow-active" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M1 1L9 5L1 9" fill="none" stroke="#173c39" stroke-width="1.5"/></marker></defs><rect width="900" height="1500" fill="#fffefb"/><g font-family="Arial, sans-serif">${paths}${pill(210,240,'TEI')}${pill(690,240,'Markdown')}${pill(210,640,'Universität')}${pill(690,640,'Individuell')}${pill(210,920,'Gleicher Host')}${pill(690,920,'Anderer Host')}${nodes}<text x="450" y="1405" text-anchor="middle" fill="#173c39" font-size="15">Gestrichelte Pfeile: mögliche Ausgaben nach einer geprüften Freigabe.</text><text x="450" y="1435" text-anchor="middle" fill="#173c39" font-size="14">${esc(note)}</text><text x="450" y="1462" text-anchor="middle" fill="#52645b" font-size="13">Eigenes Publikationsrepo auf beiden Wegen. Aktuelle Auswahl ist Planung, kein Umsetzungsnachweis.</text><text x="450" y="1486" text-anchor="middle" fill="#52645b" font-size="12">Editionskompass · Anna · 20. Oktober 2026</text></g></svg>`;
}
